type ChoiceId = 'a' | 'b' | 'c' | 'd'

function q(
  number: number,
  prompt: string,
  choices: [string, string, string, string],
  correctChoiceIds: ChoiceId[],
  explanation: string,
  reference: keyof typeof refs,
): Question {
  const [title, url] = refs[reference]
  return {
    id: `sc500-identity-${String(number).padStart(3, '0')}`,
    domainId: 'identity-governance',
    prompt,
    choices: [
      { id: 'a', text: choices[0] },
      { id: 'b', text: choices[1] },
      { id: 'c', text: choices[2] },
      { id: 'd', text: choices[3] },
    ],
    correctChoiceIds,
    explanation,
    references: [{ title, url }],
  }
}

